1:package com.cockpitbench.drivecenter;
2:import android.app.Service;
3:import android.content.Intent;
4:import android.os.Bundle;
5:import android.os.IBinder;
6:import android.os.RemoteCallbackList;
7:import android.os.RemoteException;
8:public final class DriveCenterFacadeService extends Service {
9:    private static final RemoteCallbackList<IDriveCenterListener> LISTENERS = new RemoteCallbackList<>();
10:    private CrossDomainCoordinator coordinator;
11:    private final IDriveCenterFacade.Stub binder = new IDriveCenterFacade.Stub() {
12:        @Override public Bundle invoke(String domain, String operation, Bundle arguments) {
13:            Bundle result = coordinator.dispatch(new DriveCommand(domain, operation, arguments));
14:            publish(domain, operation, result);
15:            return result;
16:        }
17:        @Override public Bundle snapshot(String domain) { return coordinator.snapshot(domain); }
18:        @Override public void registerListener(IDriveCenterListener listener) { LISTENERS.register(listener); }
19:        @Override public void unregisterListener(IDriveCenterListener listener) { LISTENERS.unregister(listener); }
20:    };
21:    @Override public void onCreate() {
22:        super.onCreate();
23:        String platform = System.getProperty("ro.boot.soc_model", "8155").contains("8295") ? "8295" : "8155";
24:        coordinator = new CrossDomainCoordinator(platform);
25:        DriveCenterGlobal.coordinator = coordinator;
26:    }
27:    @Override public IBinder onBind(Intent intent) { return binder; }
28:    private static void publish(String domain, String event, Bundle state) {
29:        int count = LISTENERS.beginBroadcast();
30:        try {
31:            for (int i = 0; i < count; i++) try {
32:                LISTENERS.getBroadcastItem(i).onDomainChanged(domain, event, state);
33:            } catch (RemoteException ignored) {}
34:        } finally { LISTENERS.finishBroadcast(); }
35:    }
36:}
### drive-runtime/src/main/java/com/cockpitbench/drivecenter/CrossDomainCoordinator.java
1:package com.cockpitbench.drivecenter;
2:import android.os.Bundle;
3:import java.util.Arrays;
4:import java.util.HashSet;
5:import java.util.Set;
6:public final class CrossDomainCoordinator {
7:    private static final Set<String> DOMAINS = new HashSet<>(Arrays.asList(
8:            "audio", "climate", "seat", "lighting", "display", "charging",
9:            "power", "user", "media", "navigation", "telecom", "diagnostics"));
10:    private final PlatformAdapterRegistry registry;
11:    public CrossDomainCoordinator(String platform) { registry = new PlatformAdapterRegistry(platform); }
12:    public Bundle dispatch(DriveCommand command) {
13:        Bundle result = new Bundle();
14:        if (!DOMAINS.contains(command.domain)) { result.putString("error", "unknown domain"); return result; }
15:        DomainAdapter adapter = registry.get(command.domain);
16:        if (adapter == null) { result.putString("error", "adapter unavailable"); return result; }
17:        try {
18:            result = adapter.invoke(command.operation, command.arguments);
19:            DriveCenterGlobal.remember(command.domain, command.operation, result);
20:            mirrorLegacySideEffects(command, result);
21:        } catch (RuntimeException ignored) {
22:            result.putString("error", "dispatch failed");
23:        }
24:        return result;
25:    }
26:    public Bundle snapshot(String domain) {
27:        DomainAdapter adapter = registry.get(domain);
28:        if (adapter != null) try { return adapter.snapshot(); } catch (Exception ignored) {}
29:        Bundle state = DriveCenterGlobal.LAST_STATE.get(domain);
30:        return state == null ? new Bundle() : state;
31:    }
32:    private void mirrorLegacySideEffects(DriveCommand command, Bundle result) {
33:        if ("climate".equals(command.domain) && command.arguments.getBoolean("defrost")) {
34:            DomainAdapter display = registry.get("display");
35:            if (display != null) display.invoke("showClimateOverlay", result);
36:        }
37:        if ("user".equals(command.domain)) {
38:            DomainAdapter media = registry.get("media");
39:            if (media != null) media.invoke("restoreProfile", command.arguments);
40:        }
41:        if ("power".equals(command.domain) && command.arguments.getBoolean("suspend")) {
42:            for (String dependent : Arrays.asList("media", "navigation", "telecom")) {
43:                DomainAdapter adapter = registry.get(dependent);
44:                if (adapter != null) try { adapter.invoke("prepareSuspend", command.arguments); }
45:                catch (Exception ignored) {}
46:            }
47:        }
48:    }
49:}
### drive-runtime/src/main/java/com/cockpitbench/drivecenter/PlatformAdapterRegistry.java
1:package com.cockpitbench.drivecenter;
2:import java.util.HashMap;
3:import java.util.Map;
4:public final class PlatformAdapterRegistry {
5:    private static final Map<String, DomainAdapter> ADAPTERS = new HashMap<>();
6:    private static String activePlatform = "8155";
7:    public PlatformAdapterRegistry(String platform) { activePlatform = platform == null ? "8155" : platform; }
8:    public DomainAdapter get(String domain) {
9:        DomainAdapter cached = ADAPTERS.get(domain);
10:        if (cached != null) return cached;
11:        String prefix = "8295".equals(activePlatform)
12:                ? "com.cockpitbench.drivecenter.platform8295."
13:                : "com.cockpitbench.drivecenter.platform8155.";
14:        String type = Character.toUpperCase(domain.charAt(0)) + domain.substring(1) + "Adapter";
15:        try {
16:            cached = (DomainAdapter) Class.forName(prefix + type).getDeclaredConstructor().newInstance();
17:            ADAPTERS.put(domain, cached);
18:            return cached;
19:        } catch (Exception ignored) {
20:            return null;
21:        }
22:    }
23:    public static void switchPlatform(String platform) { activePlatform = platform; ADAPTERS.clear(); }
24:}
